          "ਗੁਰੂ ਅਰਜਨ ਦੇਵ ਜੀ ਦਾ ਜਨਮ 15 ਅਪਰੈਲ 1563 ਨੂੰ ਗੋਇੰਦਵਾਲ ਵਿੱਚ ਗੁਰੂ ਰਾਮਦਾਸ ਜੀ ਅਤੇ ਮਾਤਾ ਭਾਨੀ ਜੀ ਦੇ ਘਰ ਹੋਇਆ।",
          "ਮੁੱਢਲੀ ਸਿੱਖਿਆ ਬਾਬਾ ਬੁੱਢਾ ਜੀ ਤੋਂ ਲਈ; ਪਿਤਾ ਜੀ ਨੇ ਯੋਗਤਾ ਵੇਖ ਕੇ 1581 ਵਿੱਚ ਉਹਨਾਂ ਨੂੰ ਗੁਰਗੱਦੀ ਸੌਂਪੀ।",
          "ਉਹ ਗੁਰ-ਪਿਤਾ ਦੇ ਹੁਕਮ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੰਨਦੇ ਸਨ; ਲਾਹੌਰ ਵਿੱਚ ਵਿਛੋੜੇ ਵੇਲੇ ਉਹਨਾਂ ਦੀ ਰਚੀ ਬਾਣੀ ਸ਼ਾਇਦ ਪਹਿਲੀ ਰਚਨਾ ਸੀ।"
