          "ਉਹਨਾਂ ਨੇ ਸ੍ਰੀ ਹਰਿਮੰਦਰ ਸਾਹਿਬ ਦੀ ਨੀਂਹ ਰਖਵਾਈ ਅਤੇ ਹੋਰ ਭਲਾਈ ਦੇ ਕਾਰਜ ਕੀਤੇ।",
          "ਮੁਗ਼ਲ ਹਕੂਮਤ ਨੇ ਉਹਨਾਂ ਨੂੰ ਤਸੀਹੇ ਦਿੱਤੇ; ਉਹ ਸਮਝੌਤੇ ਲਈ ਨਹੀਂ ਝੁਕੇ ਅਤੇ ਲਾਹੌਰ ਵਿੱਚ ਸ਼ਹੀਦ ਹੋਏ। ਇਸ ਲਈ ਉਹਨਾਂ ਨੂੰ ਸ਼ਹੀਦਾਂ ਦੇ ਸਰਤਾਜ ਕਹਿੰਦੇ ਹਨ।"
