        { q: "ਆਦਿ ਗ੍ਰੰਥ ਦੀ ਸੰਪਾਦਨਾ ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਕੀ ਯੋਗਦਾਨ ਹੈ?", a: "ਉਹਨਾਂ ਨੇ ਗੁਰੂਆਂ ਤੇ ਭਗਤਾਂ ਦੀ ਬਾਣੀ ਇਕੱਠੀ ਕਰ ਕੇ ਰਾਗਾਂ ਅਨੁਸਾਰ ਤਰਤੀਬ ਦਿੱਤੀ ਅਤੇ ਲਿਖਾਈ ਭਾਈ ਗੁਰਦਾਸ ਜੀ ਤੋਂ ਕਰਵਾਈ।" },
        { q: "ਉਹਨਾਂ ਨੂੰ ਸ਼ਹੀਦਾਂ ਦੇ ਸਰਤਾਜ ਕਿਉਂ ਕਿਹਾ ਜਾਂਦਾ ਹੈ?", a: "ਸਿੱਖ ਧਰਮ ਵਿੱਚ ਪਹਿਲੀ ਸ਼ਹੀਦੀ ਉਹਨਾਂ ਦੀ ਹੋਈ; ਉਹਨਾਂ ਨੇ ਤਸੀਹੇ ਸਹਿ ਕੇ ਵੀ ਸਮਝੌਤਾ ਨਹੀਂ ਕੀਤਾ।" }
