          "ਹਾਰ ਮਿਲੇ ਤਾਂ ਵੀ ਨਿਰਾਸ ਨਹੀਂ ਹੋਣਾ, ਜਿੱਤ ਵਿੱਚ ਵਿਸ਼ਵਾਸ ਰੱਖਣਾ ਹੈ।"
