        { q: "ਲੇਖਕ ਅਨੁਸਾਰ ਅੱਜ-ਕੱਲ੍ਹ ਗਿੱਧੇ ਦੀ ਪਰੰਪਰਾ ਨਾਲ ਕੀ ਹੋ ਰਿਹਾ ਹੈ?", options: ["ਬਹੁਤ ਵਧ ਰਹੀ ਹੈ", "ਮੱਧਮ ਪੈ ਰਹੀ ਹੈ", "ਬੰਦ ਹੋ ਚੁੱਕੀ ਹੈ", "ਬਦਲ ਗਈ ਹੈ"], answer: 1, explain: "ਮਨੋਰੰਜਨ ਦੇ ਸਾਧਨ ਬਦਲਣ ਕਰ ਕੇ ਇਹ ਪਰੰਪਰਾ ਮੱਧਮ ਪੈ ਰਹੀ ਹੈ।" }
