      section: "ਪੰਜਾਬੀ ਪੁਸਤਕ",
      summary: "ਜਨਕਰਾਜ ਸਿੰਘ ਦੀ ਇਸ ਜੀਵਨੀ ਵਿੱਚ ਵਿਗਿਆਨੀ, ਸਾਹਿਤ ਤੇ ਕਲਾ ਦੇ ਰਸੀਏ ਡਾ. ਰੰਧਾਵਾ ਦੀ ਬਹੁਪੱਖੀ ਸ਼ਖ਼ਸੀਅਤ ਅਤੇ ਪੰਜਾਬ ਲਈ ਕੀਤੇ ਕੰਮਾਂ ਦਾ ਵਰਨਣ ਹੈ।",
