          "ਉਹਨਾਂ ਨੇ ਲੋਕ-ਗੀਤ ਇਕੱਠੇ ਕਰਨ ਵੇਲੇ ਵਿਗਿਆਨਕ ਢੰਗ ਅਪਣਾਇਆ ਅਤੇ ਲੋਕਾਂ ਕੋਲੋਂ ਉਹਨਾਂ ਦੀ ਬੋਲੀ ਵਿੱਚ ਸੁਣ ਕੇ, ਬਿਨਾਂ ਬਦਲੇ ਗੀਤ ਸੰਭਾਲੇ।"
