        { q: "ਕਹਾਣੀ ਦਾ ਨਾਂ “ਸਾਂਝੀ ਮਾਂ” ਕਿਉਂ ਢੁਕਵਾਂ ਹੈ?", a: "ਪੰਜਾਬ ਕੌਰ ਆਪਣੇ ਬੱਚਿਆਂ ਦੇ ਨਾਲ-ਨਾਲ ਸਾਰੇ ਫ਼ੌਜੀ ਜਵਾਨਾਂ ਲਈ ਵੀ ਮਾਂ ਵਰਗੀ ਹੈ।" }
