      title: "ਰਾਬਿੰਦਰ ਨਾਥ ਟੈਗੋਰ (ਜੀਵਨੀ)",
      section: "ਪੰਜਾਬੀ ਪੁਸਤਕ",
      summary: "ਰਵਿੰਦਰ ਕੌਰ ਦੀ ਇਸ ਜੀਵਨੀ ਵਿੱਚ ਰਾਸ਼ਟਰੀ ਗਾਨ ਦੇ ਰਚਣਹਾਰ ਗੁਰੂਦੇਵ ਟੈਗੋਰ ਦੇ ਬਚਪਨ, ਰਚਨਾਵਾਂ, ਸ਼ਾਂਤੀ ਨਿਕੇਤਨ ਅਤੇ ਦੇਸ-ਪ੍ਰੇਮ ਦਾ ਵੇਰਵਾ ਹੈ।",
