          "ਗੇਂਦ ਉਸ ਦੀ ਸਟਿੱਕ ਨਾਲ ਚਿਪਕੀ ਜਾਪਦੀ ਸੀ, ਇਸ ਲਈ ਉਸ ਨੂੰ ‘ਹਾਕੀ ਦਾ ਜਾਦੂਗਰ’ ਕਿਹਾ ਜਾਂਦਾ ਹੈ।"
